const d = $input.first().json;
d.status = d.leadScore > 70 ? 'hot_emailed' : (d.leadScore > 0 ? 'nurture' : 'invalid');
const lead = {
  lead_id: d.leadId, name: d.name, email: d.email, phone: d.phone,
  company: d.enrichedCompany || d.company || '',
  company_industry: d.enrichedIndustry || '',
  company_size: d.enrichedSize || '',
  role: d.position || d.enrichedRole || (d.companyFound ? 'Executive' : 'UNKNOWN EXECUTIVE'),
  source: d.source, message: d.message,
  lead_score: d.leadScore, lead_tier: d.leadTier, priority: d.priority,
  prompt_version: d.promptVersion, status: d.status, next_action: d.nextAction
};
const esc = (v) => v === null || v === undefined ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const cols = Object.keys(lead);
const vals = cols.map(c => esc(lead[c]));
const updates = cols.filter(c => c !== 'lead_id').map(c => c + ' = EXCLUDED.' + c);
const crm_sql = 'INSERT INTO leads_leads (' + cols.join(', ') + ') VALUES (' + vals.join(', ') + ') ON CONFLICT (lead_id) DO UPDATE SET ' + updates.join(', ') + ', updated_at = NOW();';
return [{ ...lead, crm_sql }];

const response = $input.first().json;
const lead = $('Prep MCP Enrich').first().json;

let text = '';
if (typeof response === 'string') {
  text = response;
} else if (response.body && typeof response.body === 'string') {
  text = response.body;
} else if (response.data && typeof response.data === 'string') {
  text = response.data;
} else {
  text = JSON.stringify(response);
}

let mcpResult = null;
const dataMatch = text.match(/data:\s*({.*})/);
if (dataMatch) {
  try {
    mcpResult = JSON.parse(dataMatch[1]);
  } catch (e) {}
} else {
  mcpResult = response;
}

const contentText = mcpResult?.result?.content?.[0]?.text;
let rows = [];
if (contentText) {
  try {
    rows = JSON.parse(contentText);
  } catch (e) {}
}

const d = { ...lead };
if (rows && rows.length > 0) {
  const row = rows[0];
  d.enrichedName = row.contact_name || undefined;
  d.enrichedRole = row.contact_role || undefined;
  d.enrichedCompany = row.company_name || undefined;
  d.enrichedIndustry = row.company_industry || undefined;
  d.enrichedSize = row.company_size || undefined;
  d.enrichedDomain = row.company_domain || undefined;
  d.contactFound = !!row.contact_found;
  d.companyFound = !!row.company_found;
} else {
  d.contactFound = false;
  d.companyFound = false;
}

if (!d.enrichedCompany) {
  d.enrichedCompany = d.company;
}

delete d.mcp_sql;
return [d];
